/* From Uiverse.io by andrew-demchenk0 - Tags: radio */
.__UIV_SCOPE__ .wrapper {
  position: relative;
  display: flex;
  flex-direction: row;
  gap: 10px;
}

.__UIV_SCOPE__ .card {
  position: relative;
  width: 150px;
  height: 100px;
  background: #fff;
  border-radius: 10px;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.05);
}

.__UIV_SCOPE__ .input {
  position: relative;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  cursor: pointer;
  appearance: none;
  border: 1px solid #e5e5e5;
  border-radius: 10px;
  z-index: 10;
  box-shadow: 1px 1px 10px #aaaaaa,
              -1px -1px 10px #ffffff;
}

.__UIV_SCOPE__ .input + .check::before {
  content: "";
  position: absolute;
  top: 15px;
  right: 15px;
  width: 16px;
  height: 16px;
  border: 2px solid #d0d0d0;
  border-radius: 50%;
  background-color: #E8E8E8;
}

.__UIV_SCOPE__ .input:checked + .check::after {
  content: '';
  position: absolute;
  top: 19px;
  right: 19px;
  width: 12px;
  height: 12px;
  background-color: rgba(255,0,0,0.7);
  border-radius: 50%;
}

.__UIV_SCOPE__ .input[value="standart"]:checked + .check::after {
  background-color: rgba(255,165,0,0.7);
}

.__UIV_SCOPE__ .input[value="premium"]:checked + .check::after {
  background-color: rgba(0,128,0,0.7);
}

.__UIV_SCOPE__ .input[value="basic"]:checked {
  border: 1.5px solid rgba(255,0,0,0.7);
}

.__UIV_SCOPE__ .input[value="standart"]:checked {
  border: 1.5px solid rgba(255,165,0,0.7);
}

.__UIV_SCOPE__ .input[value="premium"]:checked {
  border: 1.5px solid rgba(0,128,0,0.7);
}

.__UIV_SCOPE__ .label {
  color: #323232;
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
}

.__UIV_SCOPE__ .label .title {
  margin: 15px 0 0 15px;
  font-weight: 900;
  font-size: 15px;
  letter-spacing: 1.5px;
}

.__UIV_SCOPE__ .label .price {
  margin: 20px 0 0 15px;
  font-size: 20px;
  font-weight: 900;
}

.__UIV_SCOPE__ .label .span {
  color: gray;
  font-weight: 700;
  font-size: 15px;
}
